<template><section class="sandbox-form"><div class="field-grid"><label>店铺名称<input v-model="form.storeName" placeholder="例如：校园优选店" /></label><label>经营类目<input v-model="form.businessCategory" placeholder="例如：日用百货" /></label><label>提现账号<input v-model="form.withdrawalAccount" inputmode="numeric" placeholder="教学模拟账号" /></label><label>运费模板<input v-model="form.freightTemplateName" placeholder="例如：全国包邮" /></label><label>计费方式<select v-model="form.freightChargeType"><option value="PIECE">按件计费</option><option value="WEIGHT">按重量计费</option></select></label></div><p class="helper">这是与当前 StudentTask 绑定的教学沙盒，数据不会进入真实商业店铺。</p></section></template>
<script setup lang="ts">const props = defineProps<{ modelValue: Record<string, unknown> }>(); const emit = defineEmits<{ 'update:modelValue': [Record<string, unknown>] }>(); const form = computed({ get: () => props.modelValue, set: value => emit('update:modelValue', value) }); watch(form, value => emit('update:modelValue', { ...value }), { deep: true })</script>
<style scoped>.sandbox-form{padding:4px}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}label{display:grid;gap:7px;color:#344054;font-size:13px;font-weight:700}input,select{width:100%;box-sizing:border-box;min-height:40px;padding:0 11px;border:1px solid #d0d5dd;border-radius:6px;background:#fff;color:#172033;font:inherit;font-weight:400}input:focus,select:focus{outline:2px solid #b2ddff;border-color:#1677ff}.helper{margin:18px 0 0;color:#7b8494;font-size:12px}@media(max-width:560px){.field-grid{grid-template-columns:1fr}}</style>
